{
  "uriTemplate": "db://orders/{orderId}",
  "name": "Order by ID",
  "description": "Fetch a single order record by its numeric order ID",
  "mimeType": "application/json"
}

def read_resource(uri):
    order_id = extract_order_id(uri)
    if not order_id.isdigit():
        raise InvalidResourceError("orderId must be numeric")
    order = order_db.find(order_id)
    if order is None:
        raise ResourceNotFoundError(f"No such order: {order_id}")
    return order

